using Weles.Core.Enums;

namespace Weles.Core.Entities;

/// <summary>
/// A report or export file generated by WELES (PDF, JSON, ZIP) – kept in the reports/exports directory with its
/// SHA-256, so the user can download it again and verify that a copy was not changed.
/// </summary>
public class AuditReport
{
    public int Id { get; set; }

    /// <summary>The audit (completed scan) the file describes; null for a file made from an imported audit.</summary>
    public int? ScanId { get; set; }
    public Scan? Scan { get; set; }

    public int? ImportedAuditId { get; set; }
    public ImportedAudit? ImportedAudit { get; set; }

    public ReportFormat Format { get; set; }

    /// <summary>File name inside the reports/exports directory – never a path chosen by the user.</summary>
    public required string FileName { get; set; }
    public long SizeBytes { get; set; }
    public required string Sha256 { get; set; }
    public DateTime CreatedAt { get; set; }

    /// <summary>"pl" or "en" – the language of a PDF report.</summary>
    public string? Language { get; set; }
}

/// <summary>
/// The AI summary of one audit – generated only when the user asks for it, from the audit's data alone, and included
/// in the PDF report and the export.
/// </summary>
public class AuditAiSummary
{
    public int Id { get; set; }
    public int ScanId { get; set; }
    public Scan? Scan { get; set; }

    public required string Text { get; set; }
    public string? Model { get; set; }
    public string Language { get; set; } = "pl";
    public DateTime CreatedAt { get; set; }
}

/// <summary>
/// An audit imported from an export of another WELES installation. Kept as a read-only snapshot and never merged into
/// the local inventory – it describes another network, at another time, and would distort local risk and monitoring.
/// </summary>
public class ImportedAudit
{
    public int Id { get; set; }
    public required string Title { get; set; }

    /// <summary>Scan number in the installation that exported it.</summary>
    public int OriginalScanId { get; set; }
    public DateTime AuditStartedAt { get; set; }
    public DateTime ExportedAt { get; set; }
    public string? ExportedBy { get; set; }
    public int SchemaVersion { get; set; }
    public int DeviceCount { get; set; }
    public double? PostureScore { get; set; }

    public required string SourceFileName { get; set; }

    /// <summary>SHA-256 of the audit JSON – the same audit is not imported twice.</summary>
    public required string Sha256 { get; set; }
    public DateTime ImportedAt { get; set; }

    /// <summary>The validated audit document (<see cref="Reports.AuditDocument"/>) as JSON.</summary>
    public required string DocumentJson { get; set; }
}
